export default "#!/usr/bin/env python3\n\"\"\"Explicitly update only the versioned AGENTS/CLAUDE managed blocks.\"\"\"\nfrom pathlib import Path\nimport argparse\nimport sys\n\nsys.dont_write_bytecode = True\nimport migrate_context as migration\n\n\ndef run(target: Path, mode: str) -> int:\n    target = target.expanduser().resolve()\n    if not target.is_dir():\n        print(\"RULE_BLOCKS_FAILED: project directory does not exist\")\n        return 2\n    try:\n        paths = [migration.rule_path(target, name) for name in (\"AGENTS.md\", \"CLAUDE.md\")]\n        originals = {path: path.read_bytes() if path.exists() else None for path in paths}\n        if mode == \"check\":\n            for path, original in originals.items():\n                span = migration.managed_block_span(original.decode(\"utf-8\")) if original else None\n                if span is None or span[2] != migration.RULES_VERSION:\n                    raise ValueError(f\"{path.name}: missing or outdated version\")\n            print(f\"RULE_BLOCKS_CURRENT: {migration.RULES_VERSION}; rule version only, not business tests or formal delivery\")\n            return 0\n        preview = [migration.plan_rule_file(target, name, target.name, False) for name in (\"AGENTS.md\", \"CLAUDE.md\")]\n        if mode != \"ensure\" or any(operation.action == \"conflict\" for operation in preview):\n            for operation in preview:\n                print(f\"{operation.action}: {operation.path.name} — {operation.reason}\")\n        if any(operation.action == \"conflict\" for operation in preview):\n            print(\"RULE_BLOCKS_CONFLICT: no project files changed\")\n            return 2\n        if mode in {\"apply\", \"ensure\"}:\n            for path, original in originals.items():\n                if (path.read_bytes() if path.exists() else None) != original:\n                    raise ValueError(f\"{path.name}: changed during preflight\")\n            operations = [migration.plan_rule_file(target, name, target.name, True) for name in (\"AGENTS.md\", \"CLAUDE.md\")]\n            if any(operation.action == \"conflict\" for operation in operations):\n                return 2\n            if mode == \"ensure\":\n                for path in paths:\n                    span = migration.managed_block_span(path.read_text(encoding=\"utf-8\"))\n                    if span is None or span[2] != migration.RULES_VERSION:\n                        raise ValueError(f\"{path.name}: update verification failed\")\n                status = \"CURRENT\" if all(operation.action == \"skip\" for operation in preview) else \"UPDATED\"\n                print(f\"RULE_BLOCKS_{status}: {migration.RULES_VERSION}; docs and project scripts untouched\")\n                return 0\n        print(f\"RULE_BLOCKS_READY: target version {migration.RULES_VERSION}; docs and project scripts untouched\")\n        return 0\n    except (OSError, UnicodeError, ValueError) as exc:\n        print(f\"RULE_BLOCKS_FAILED: {exc}\")\n        return 2\n\n\nif __name__ == \"__main__\":\n    parser = argparse.ArgumentParser(description=__doc__)\n    parser.add_argument(\"--target\", default=\".\")\n    parser.add_argument(\"--mode\", choices=(\"dry-run\", \"apply\", \"check\", \"ensure\"), default=\"dry-run\")\n    args = parser.parse_args()\n    raise SystemExit(run(Path(args.target), args.mode))\n";
